```javascript
const { Client, GatewayIntentBits } = require('discord.js');
const { REST } = require('@discordjs/rest');
const { Routes } = require('discord-api-types/v9');
const { join } = require('path');

const client = new Client({ intents: [GatewayIntentBits.Guilds] });
const rest = new REST({ version: '9' }).setToken(process.env.DISCORD_TOKEN);

// Load Slash Commands
const commands = [];
const commandFiles = process.cwd().split(path.sep).slice(1).slice(0, -1).join(path.sep) + '\\commands\\**\\*.js';
const commandPath = join(process.cwd(), commandFiles);
client.commands = new Collection();

for (const file of fs.readdirSync(commandPath, { withFileTypes: true })) {
  if (file.isDirectory()) {
    continue;
  }

  const command = require(`../commands/${file.name}`);
  commands.push(command.data.toJSON());
  client.commands.set(command.data.name, command);
}

(async () => {
  try {
    console.log('Started refreshing application (/) commands.');

    await rest.put(
      Routes.applicationCommands(process.env.CLIENT_ID),
      { body: commands },
    );

    console.log('Successfully reloaded application (/) commands.');
  } catch (error) {
    console.error(error);
  }
})();

// Load Event Handlers
const events = {};
const eventPath = join(process.cwd(), 'events', '**', '*.js');
fs.readdirSync(eventPath, { withFileTypes: true }).forEach((file) => {
  if (file.isDirectory()) {
    return;
  }

  const eventName = file.name.slice(0, -3);
  const event = require(`../events/${file.name}`);

  events[eventName] = event.bind(null, client);
});

Object.keys(events).forEach((eventName) => {
  client.on(eventName, events[eventName]);
});

client.on('ready', () => {
  console.log('Discord bot is ready!');
});

client.login(process.env.DISCORD_TOKEN);
```

