Написание игры «Змейка» на C, которая будет плавной и будет использовать изображения для анимации всего уровня, потребует определенных знаний и навыков в области разработки игр. В этой статье приведен обзор основных этапов, которые могут помочь вам в создании такой игры.

1. Сетuptools и библиотеки

Сначала вам потребуется настроить среду разработки и установить необходимые библиотеки. В качестве примера, мы будем использовать CMake для настройки и сборки проекта, SDL2 для работы с графическим интерфейсом, и OpenGL для создания анимации.

Следуйте инструкциям по установке CMake и SDL2 для вашей операционной системы.

2. Создание игрового экрана

Следующим шагом будет создание игрового экрана, на котором будет отображаться змейка и окружающая среда. Для этого потребуется создать окно с помощью SDL2, инициализировать OpenGL и загрузить изображения с помощью библиотеки загрузки изображений.

Вот пример кода для создания игрового экрана:

```c
#include <SDL2/SDL.h>
#include <SDL2/SDL_opengl.h>
#include <SDL2/SDL_image.h>

#include <iostream>
#include <fstream>

#include "Snake.h"
#include "Food.h"

const int WINDOW_WIDTH = 800;
const int WINDOW_HEIGHT = 600;

// Функция для инициализации SDL2 и OpenGL
bool initSDL();

// Функция для загрузки текстур с помощью SDL_image
Texture2D loadTexture(const char* filename);

int main(int argc, char* argv[]) {
    if (!initSDL()) {
        std::cout << "SDL2 initialization failed" << std::endl;
        return 1;
    }

    // Инициализация OpenGL
    glEnable(GL_TEXTURE_2D);
    glClearColor(0.2f, 0.2f, 0.2f, 1.0f);

    // Загрузка текстур
    Texture2D backgroundTexture = loadTexture("background.png");
    Texture2D snakeTexture = loadTexture("snake.png");
    Texture2D foodTexture = loadTexture("food.png");

    // Создание змейки и еды
    Snake snake(WINDOW_WIDTH, WINDOW_HEIGHT);
    Food food(WINDOW_WIDTH, WINDOW_HEIGHT);

    // Цикл игры
    while (true) {
        // Обработка событий
        SDL_Event e;
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) {
                return 0;
            }
            snake.handleEvent(e);
        }

        // Обновление змейки и еды
        snake.update();
        food.update();

        // Отрисовка экрана
        glClear(GL_COLOR_BUFFER_BIT);
        glBindTexture(GL_TEXTURE_2D, backgroundTexture.id);
        glBegin(GL_QUADS);
        glVertex2f(0, 0);
        glVertex2f(WINDOW_WIDTH, 0);
        glVertex2f(WINDOW_WIDTH, WINDOW_HEIGHT);
        glVertex2f(0, WINDOW_HEIGHT);
        glEnd();

        glBindTexture(GL_TEXTURE_2D, snakeTexture.id);
        snake.render();

        glBindTexture(GL_TEXTURE_2D, foodTexture.id);
        food.render();

        SDL_GL_SwapBuffers();
    }

    return 0;
}

bool initSDL() {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_GL_SetAttribute(SDL_GL_DOUBLEBUFFER, 1);
    SDL_GL_SetAttribute(SDL_GL_DEPTH_SIZE, 24);

    SDL_Window* window = SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_OPENGL | SDL_WINDOW_RESIZABLE
    );

    if (window == nullptr) {
        std::cout << "SDL2 window creation failed: " << SDL_GetError() << std::endl;
        return false;
    }

    SDL_GLContext context = SDL_GL_CreateContext(window);

    if (context == nullptr) {
        std::cout << "SDL2 OpenGL context creation failed: " << SDL_GetError() << std::endl;
        return false;
    }

    if (IMG_Init(IMG_INIT_PNG) != IMG_INIT_PNG) {
        std::cout << "SDL_image initialization failed: " << IMG_GetError() << std::endl;
        return false;
    }

    return true;
}

Texture2D loadTexture(const char* filename) {
    SDL_Surface* surface = IMG_Load(filename);

    if (surface == nullptr) {
        std::cout << "Failed to load texture: " << IMG_GetError() << std::endl;
        return Texture2D();
    }

    GLuint textureID;
    glGenTextures(1, &textureID);

    glBindTexture(GL_TEXTURE_2D, textureID);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);

    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGB, surface->w, surface->h, 0, GL_RGB, GL_UNSIGNED_BYTE, surface->pixels);

    SDL_FreeSurface(surface);

    return Texture2D(textureID);
}
```

3. Реализация змейки

Следующим шагом будет реализация змейки. Вам потребуется создать структуру для хранения информации о змейке, которая будет содержать данные о ее положении, длине, скорости и т. Д.

Вот пример структуры для змейки:

```c
#include <vector>

struct Point {
    int x, y;
};

struct Snake {
    std::vector<Point> body;
    int length;
    int direction;
    float speed;

    Snake(int width, int height) :
        body({ { width / 2, height / 2 } }),
        length(1),
        direction(0),
        speed(2.0f) {}

    void handleEvent(SDL_Event& e) {
        if (e.type == SDL_KEYDOWN) {
            int key = e.key.keysym.sym;
            if (key == SDLK_LEFT && direction != 1) {
                direction = 0;
            }
            else if (key == SDLK_RIGHT && direction != 0) {
                direction = 1;
            }
        }
    }

    void update() {
        Point head = body.back();
        int nx = head.x;
        int ny = head.y;

        if (direction == 0) {
            nx--;
        }
        else if (direction == 1) {
            nx++;
        }

        if (nx < 0 || nx >= WINDOW_WIDTH || ny < 0 || ny >= WINDOW_HEIGHT) {
            return;
        }

        body.pop_back();
        body.insert(body.begin(), Point(nx, ny));
    }

    void render() {
        for (const auto& p : body) {
            glBindTexture(GL_TEXTURE_2D, snakeTexture.id);
            glBegin(GL_QUADS);
            glVertex2f(p.x, p.y);
            glVertex2f(p.x + 10, p.y);
            glVertex2f(p.x + 10, p.y + 10);
            glVertex2f(p.x, p.y + 10);
            glEnd();
        }
    }
};
```

4. Реализация еды

Следующим шагом будет реализация еды. Вам потребуется создать структуру для хранения информации о еде, которая будет содержать данные о ее положении и текстуру.

Вот пример структуры для еды:

```c
struct Food {
    Point position;
    Texture2D texture;

    Food(int width, int height) :
        position({ rand() % width, rand() % height }),
        texture(foodTexture.id) {}

    void update() {
        position.x = rand() % (WINDOW_WIDTH - 10) + 5;
        position.y = rand() % (WINDOW_HEIGHT - 10) + 5;
    }

    void render() {
        glBindTexture(GL_TEXTURE_2D, texture.id);
        glBegin(GL_QUADS);
        glVertex2f(position.x, position.y);
        glVertex2f(position.x + 10, position.y);
        glVertex2f(position.x + 10, position.y + 10);
        glVertex2f(position.x, position.y + 10);
        glEnd();
    }
};
```

5. Логика игры

Следующим шагом будет реализация логики игры. Вам потребуется определить, столкнулась ли змейка с собой или с едой, и обновить игровой процесс в соответствии с этим.

Вот пример кода для логики игры:

```c
#include <cstdlib>

bool checkCollision(const Snake& snake, const Point& point) {
    for (const auto& p : snake.body) {
        if (p.x == point.x && p.y == point.y) {
            return true;
        }
    }

    return false;
}

bool isGameOver(Snake& snake) {
    return checkCollision(snake, snake.body.front());
}

bool eat(Snake& snake, Food& food) {
    return checkCollision(snake, food.position);
}

int main(int argc, char* argv[]) {
    // ...

    while (true) {
        // ...

        snake.update();

        if (eat(snake, food)) {
            snake.length++;
            food.update();
        }

        if (isGameOver(snake)) {
            std::cout << "Game over!" << std::endl;
            break;
        }
    }

    // ...
}
```

6. Графическая оболочка

В качестве последнего шага, вы можете добавить графическую оболочку, которая будет отображать счет, скорость и т. Д.

Вот пример кода для графической оболочки:

```c
#include <iostream>
#include <sstream>

void drawText(GLfloat x, GLfloat y, const char* text) {
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    glEnable(GL_BLEND);
    glDisable(GL_TEXTURE_2D);

    glPushMatrix();
    glTranslatef(x, WINDOW_HEIGHT - y, 0);

    glScalef(0.5f, 0.5f, 0.5f);

    glColor4f(1.0f, 1.0f, 1.0f, 0.5f);
    glRasterPos2f(0, 0);

    for (const char c : text) {
        if (c == '\n') {
            glRasterPos2f(0, -12);
        }
        else {
            glutBitmapCharacter(GLUT_BITMAP_HELVETICA_12, c);
        }
    }

    glPopMatrix();
    glEnable(GL_TEXTURE_2D);
    glDisable(GL_BLEND);
}

void drawScore(const Snake& snake) {
    std::stringstream ss;
    ss << "Score: " << snake.length;

    drawText(10, 10, ss.str().c_str());
}

void drawSpeed(const Snake& snake) {
    std::stringstream ss;
    ss << "Speed: " << snake.speed;

    drawText(WINDOW_WIDTH - 150, 10, ss.str().c_str());
}

int main(int argc, char* argv[]) {
    // ...

    while (true) {
        // ...

        drawScore(snake);
        drawSpeed(snake);

        SDL_GL_SwapBuffers();
    }

    // ...
}
```

