```javascript
function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    let num = arr[i];
    if (isPrime(num)) {
      console.log(num);
      break; // если найдено простое число, нет необходимости проверять остальные числа
    }
  }
}

function isPrime(num) {
  if (num <= 1) return false;
  for (let I = 2; I <= Math.sqrt(num); i++) {
    if (num % I === 0) {
      return false;
    }
  }
  return true;
}

// Пример использования:
